import{_ as i,o as s,c as t,ab as a}from"./chunks/framework.lcGQrBOb.js";const k=JSON.parse('{"title":"Regenerating backend OpenAPI specifications","description":"","frontmatter":{},"headers":[],"relativePath":"openapi-spec-generation.md","filePath":"openapi-spec-generation.md"}'),n={name:"openapi-spec-generation.md"};function r(o,e,p,c,l,d){return s(),t("div",null,[...e[0]||(e[0]=[a(`<h1 id="regenerating-backend-openapi-specifications" tabindex="-1">Regenerating backend OpenAPI specifications <a class="header-anchor" href="#regenerating-backend-openapi-specifications" aria-label="Permalink to “Regenerating backend OpenAPI specifications”">​</a></h1><p>Each backend has an opt-in generation test that starts an isolated Spring MVC context with its REST controllers and mocked collaborators. It does not start the backend application or connect to its infrastructure. Java 21, Maven, and the project&#39;s Maven dependencies are required; Docker and running SLM services are not.</p><p>In VS Code, choose <strong>Tasks: Run Task</strong> and select the <code>OpenAPI:</code> task for the desired service. The generated <code>api-docs-for-ui.yaml</code> is written to that service&#39;s <code>*.service.client/src/main/resources</code> directory. Catalog and information service have client resource modules but no generated TypeScript clients. Information service currently has no scanned REST endpoints, so its <code>paths</code> is empty.</p><p>To run a task from the repository root without VS Code, substitute the application path and test class from the table:</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mvn</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -pl</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">application-pat</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">h</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -am</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Dtest=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">test-class</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -Dsurefire.failIfNoSpecifiedTests=false</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -DgenerateOpenApiSpec=true</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Service</th><th>Application path</th><th>Test class</th></tr></thead><tbody><tr><td>Platform management</td><td><code>platform_management/platform_management.service/platform_management.service.app</code></td><td><code>org.eclipse.slm.platform_management.service.app.OpenApiSpecGenerationTest</code></td></tr><tr><td>Resource management</td><td><code>resource_management/resource_management.service/resource_management.service.app</code></td><td><code>org.eclipse.slm.resource_management.service.app.OpenApiSpecGenerationTest</code></td></tr><tr><td>Service management</td><td><code>service_management/service_management.service/service_management.service.app</code></td><td><code>org.eclipse.slm.service_management.service.app.OpenApiSpecGenerationTest</code></td></tr><tr><td>Notification service</td><td><code>notification_service/notification_service.service/notification_service.service.app</code></td><td><code>org.eclipse.slm.notification_service.service.app.OpenApiSpecGenerationTest</code></td></tr><tr><td>Catalog</td><td><code>catalog/catalog.service/catalog.service.app</code></td><td><code>org.eclipse.slm.catalog.service.app.OpenApiSpecGenerationTest</code></td></tr><tr><td>Information service</td><td><code>information_service/information_service.service/information_service.service.app</code></td><td><code>org.eclipse.slm.information_service.service.app.OpenApiSpecGenerationTest</code></td></tr></tbody></table><p>The fully qualified test name ensures that building upstream dependencies does not regenerate their specifications. Normal test runs skip generation unless <code>-DgenerateOpenApiSpec=true</code> is supplied. Review the resulting changes before using them to regenerate clients.</p><p>OAuth endpoint URLs are normally discovered from the running Keycloak configuration. Since generation mocks that dependency, those URLs are empty in generated specifications; supply the appropriate values for your deployment if you need to use the specifications for Swagger UI authentication.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to “Troubleshooting”">​</a></h2><p>If the build fails with <code>cannot access &lt;SomeException&gt;</code> or <code>class file for &lt;SomeClass&gt; not found</code> for a class that clearly exists, and cleaning the module does not help, the VS Code Java extension is writing its own compiler output into the same <code>target/classes</code> directories. Those compiler stubs are newer than the sources, so Maven&#39;s incremental build accepts them instead of recompiling. This affects any Maven build in the workspace, not just spec generation.</p><p>The reliable workaround is to run the command from a checkout outside the VS Code workspace, for example:</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rsync</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -a</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --exclude</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> target</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --exclude</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/slm-verify/</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/slm-verify</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mvn</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -pl</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">application-pat</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">h</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -am</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Dtest=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">test-class</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -Dsurefire.failIfNoSpecifiedTests=false</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -DgenerateOpenApiSpec=true</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div><p>Then copy the regenerated <code>api-docs-for-ui.yaml</code> files back. Cleaning the affected module (<code>mvn -pl &lt;application-path&gt; -am clean</code>) sometimes helps, but the extension may poison another module before the build finishes.</p><p>Generated specifications are written with sorted object keys because OpenAPI objects are unordered. Regenerating an unchanged API therefore produces byte-identical files instead of diff noise.</p>`,14)])])}const g=i(n,[["render",r]]);export{k as __pageData,g as default};
